def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            c0 = min(x for y, x in cells)
            r1 = max(y for y, x in cells)
            c1 = max(x for y, x in cells)
            base = max(set(grid[y][x] for y, x in cells), key=lambda v: sum(grid[y][x] == v for y, x in cells))
            specials = [(y - r0, x - c0, grid[y][x]) for y, x in cells if grid[y][x] != base]
            objects.append((r0, c0, r1, c1, base, specials))
    target = max(objects, key=lambda o: len(o[5]))
    out = [[target[4] for _ in range(target[3] - target[1] + 1)] for _ in range(target[2] - target[0] + 1)]
    for y, x, v in target[5]:
        out[y][x] = v
    for obj in objects:
        if obj is target:
            continue
        for y, x, v in obj[5]:
            out[y][x] = v
    return out
